   606	class MineSafetyModel:
   607	    """In-memory deterministic model stepped at a fixed two-second interval."""
   608	
   609	    def __init__(self, seed: int = 42):
   610	        self.seed = seed
   611	        self.tick = 0
   612	        self.active_scenario = "none"
   613	        self.scenario_zone: str | None = None
   614	
   615	    def start_scenario(self, scenario: str, zone: str | None = None) -> None:
   616	        if scenario not in VALID_SCENARIOS:
   617	            raise ValueError(f"unknown scenario: {scenario}")
   618	        if scenario in {"methane_release", "blocked_working"} and zone not in MINING_SECTIONS:
   619	            raise ValueError(f"{scenario} requires zone section_a or section_b")
   620	        if scenario == "fire":
   621	            zone = zone or "main_drift"
   622	            if zone not in FIRE_ZONES:
   623	                raise ValueError("fire requires zone main_drift, section_a or section_b")
   624	        if scenario == "main_fan_failure":
   625	            zone = "shaft"
   626	        self.active_scenario = scenario
   627	        self.scenario_zone = zone
   628	
   629	    def reset(self) -> None:
   630	        self.tick = 0
   631	        self.active_scenario = "none"
   632	        self.scenario_zone = None
   633	
   634	    def step(self) -> dict[str, Any]:
   635	        self.tick += 1
   636	        return self.snapshot()
